fn lookup(cp: u21, rows: []const Range) Property {
    var lo: usize = 0;
    var hi = rows.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const r = rows[mid];
        if (cp < r[0]) hi = mid else if (cp > r[1]) lo = mid + 1 else return r[2];
    }
    return .other;
}
pub fn property(cp: u21) Property {
    return lookup(cp, &breaks);
}
pub fn isPictographic(cp: u21) bool {
    return lookup(cp, &emoji) == .pictographic;
}
pub fn conjunct(cp: u21) Property {
    return lookup(cp, &indic);
}
